package za.co.loopmanager;
import android.app.admin.DevicePolicyManager;import android.content.*;import android.os.UserManager;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={30,35})
public class DebugProtectionTest {
 @Test public void enrollmentWithoutCustomerIsNotBlockedButFinancedOwnerIs()throws Exception{Context c=RuntimeEnvironment.getApplication();assertFalse(c.getSystemService(UserManager.class).hasUserRestriction(UserManager.DISALLOW_DEBUGGING_FEATURES));Shadows.shadowOf(c.getSystemService(DevicePolicyManager.class)).setDeviceOwner(PolicyController.admin(c));assertFalse(StartupProtection.prefs(c).getBoolean("financed",false));PolicyController.protectFinancedDevice(c);assertTrue(c.getSystemService(UserManager.class).hasUserRestriction(UserManager.DISALLOW_DEBUGGING_FEATURES));assertTrue(StartupProtection.prefs(c).getBoolean("financed",false));assertTrue(ManagedUpdates.automaticInstallAllowed(c,new org.json.JSONObject().put("install_automatically",true).put("requires_approval",false)));assertFalse(c.getSystemService(UserManager.class).hasUserRestriction(UserManager.DISALLOW_CONFIG_WIFI));}
 @Test public void lockedBootDoesNotReadCustomerStorageAndReappliesDebugRestriction(){Context c=RuntimeEnvironment.getApplication();var pm=c.getSystemService(DevicePolicyManager.class);Shadows.shadowOf(pm).setDeviceOwner(PolicyController.admin(c));StartupProtection.record(c,true);new BootReceiver().onReceive(c,new Intent(Intent.ACTION_LOCKED_BOOT_COMPLETED));assertTrue(c.getSystemService(UserManager.class).hasUserRestriction(UserManager.DISALLOW_DEBUGGING_FEATURES));assertEquals("Android credential unlock pending",StartupProtection.prefs(c).getString("phase",""));assertFalse(StartupProtection.prefs(c).contains("device_token"));StartupProtection.record(c,false);pm.clearUserRestriction(PolicyController.admin(c),UserManager.DISALLOW_DEBUGGING_FEATURES);StartupProtection.lockedBoot(c);assertFalse(c.getSystemService(UserManager.class).hasUserRestriction(UserManager.DISALLOW_DEBUGGING_FEATURES));}
 @Test public void firstUnlockSchedulesImmediateRecoveryWithoutNetworkConstraint(){Context c=RuntimeEnvironment.getApplication();Shadows.shadowOf(c.getSystemService(DevicePolicyManager.class)).setDeviceOwner(PolicyController.admin(c));Shadows.shadowOf(c.getSystemService(UserManager.class)).setUserUnlocked(true);new BootReceiver().onReceive(c,new Intent(Intent.ACTION_USER_UNLOCKED));var recovery=c.getSystemService(android.app.job.JobScheduler.class).getPendingJob(401);assertNotNull(recovery);assertEquals(android.app.job.JobInfo.NETWORK_TYPE_NONE,recovery.getNetworkType());assertEquals("Local policy recovery requested",StartupProtection.prefs(c).getString("phase",""));}
 @Test public void payoffReleaseRemovesOurDebugRestriction()throws Exception{Context c=RuntimeEnvironment.getApplication();var pm=c.getSystemService(DevicePolicyManager.class);Shadows.shadowOf(pm).setDeviceOwner(PolicyController.admin(c));PolicyController.protectFinancedDevice(c);org.json.JSONObject data=new org.json.JSONObject().put("released",true).put("policy",new org.json.JSONObject());assertEquals("released",PolicyController.apply(c,new Entitlement(data,0,-1)));assertFalse(StartupProtection.prefs(c).getBoolean("financed",true));assertFalse(c.getSystemService(UserManager.class).hasUserRestriction(UserManager.DISALLOW_DEBUGGING_FEATURES));}
}
